/// Upstream-style data-source list surface: a grid of 35 Available cards,
/// grouped Added cards with Settings/Trash row actions, and the delete
/// confirmation dialog (`added-source-card.tsx` + `delete-source-modal.tsx`).
fn data_source_list_section(info_json: &str) -> String {
    let style = r#"<style>.ds-available-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px;margin-top:12px}.ds-available-icon{width:32px;height:32px;display:flex;align-items:center;justify-content:center;border-radius:8px;background:var(--nab);font-weight:700}.ds-available-icon img{width:26px;height:26px;object-fit:contain}.ds-added-card{margin-top:16px;border:1px solid var(--bd);border-radius:var(--rs);background:var(--bgc);padding:12px 16px}.ds-added-head{display:flex;align-items:center;gap:8px;margin:0 0 8px;font-size:16px;font-weight:500}.ds-added-row{display:flex;align-items:center;gap:12px;padding:10px 0;border-bottom:1px solid var(--bd)}.ds-added-row:last-child{border-bottom:0}.ds-added-name{flex:1;min-width:0;overflow-wrap:anywhere}.ds-added-actions{display:flex;align-items:center;gap:6px;flex-wrap:wrap}.ds-icon-btn{display:inline-flex;align-items:center;justify-content:center;width:30px;height:30px;border:0;border-radius:8px;background:transparent;color:var(--t2);cursor:pointer}.ds-icon-btn:hover{background:var(--bgch);color:var(--t)}.ds-icon-btn.ds-trash:hover{color:var(--d)}.ds-local-row{display:flex;gap:8px;align-items:flex-end}.ds-empty{color:var(--tm);padding:16px 0}</style>"#;
    let delete_modal = r#"<div class='modal-overlay' id='dsDeleteModal' data-testid='data-source-delete-modal' onclick='if(event.target===this)closeDsDelete()'><div class='modal' style='max-width:560px' role='alertdialog' aria-modal='true' aria-labelledby='dsDeleteTitle'><h2 id='dsDeleteTitle'>Delete data source</h2><p class='user-setting-description'>Are you sure you want to delete this data source link?</p><div id='dsDeleteBox' class='ds-delete-box'></div><div class='provider-instance-actions'><button class='btn btn-o' type='button' onclick='closeDsDelete()'>Cancel</button><button class='btn btn-d' id='dsDeleteOk' type='button' onclick='confirmDsDelete()'>Confirm</button></div></div></div>"#;
    let js = r#"<script>var DS_SOURCE_INFO=__INFO__;var DS_DELETE_ID='';function dsIconHtml(info){if(info&&info.icon&&info.icon.indexOf('.svg')>=0)return "<img src='/"+info.icon+"' alt='' aria-hidden='true'>";return info&&info.icon||'🔗'}function dsRenderCards(){var root=document.getElementById('dsAvailable');root.replaceChildren();Object.keys(DS_SOURCE_INFO).forEach(function(key){var info=DS_SOURCE_INFO[key];var card=document.createElement('article');card.className='cc-available-card';card.dataset.type=key;card.tabIndex=0;var icon=document.createElement('span');icon.className='cc-available-icon ds-available-icon';icon.innerHTML=dsIconHtml(info);var title=document.createElement('h3');title.textContent=info.name;var desc=document.createElement('p');desc.className='cc-available-desc ds-available-desc';desc.textContent=info.description||'';var add=document.createElement('button');add.className='cc-add-btn btn btn-p btn-sm';add.type='button';add.textContent='+ Add';add.addEventListener('click',function(event){event.stopPropagation();openDsAdd(key,info.name)});card.addEventListener('click',function(){openDsAdd(key,info.name)});card.append(icon,title,desc,add);root.appendChild(card)})}function dsGroupedRows(list){var groups={};list.forEach(function(item){(groups[item.type]=groups[item.type]||[]).push(item)});return groups}function loadDs(){fetch('/api/v1/data_sources').then(function(response){return response.json()}).then(function(data){var list=data.data||[];var root=document.getElementById('dsList');root.replaceChildren();if(!list.length){var empty=document.createElement('p');empty.className='ds-empty';empty.textContent='No data sources added yet.';root.appendChild(empty);return}var groups=dsGroupedRows(list);Object.keys(groups).forEach(function(type){var info=DS_SOURCE_INFO[type]||{name:type,icon:'🔗'};var card=document.createElement('div');card.className='ds-added-card';card.dataset.type=type;var head=document.createElement('h2');head.className='ds-added-head';var headIcon=document.createElement('span');headIcon.className='ds-available-icon';headIcon.innerHTML=dsIconHtml(info);head.appendChild(headIcon);var headName=document.createElement('span');headName.textContent=info.name;head.appendChild(headName);card.appendChild(head);groups[type].forEach(function(item){var row=document.createElement('div');row.className='ds-added-row';var name=document.createElement('span');name.className='ds-added-name';name.textContent=item.name;var badge=document.createElement('span');badge.className=item.connected?'badge bs':'badge bw';badge.textContent=item.connected?'connected':'disconnected';var actions=document.createElement('span');actions.className='ds-added-actions';var gear=document.createElement('button');gear.type='button';gear.className='ds-icon-btn';gear.title='Settings';gear.innerHTML='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 1 1-2.83 2.83l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 1 1-4 0v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 1 1-2.83-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 1 1 0-4h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 1 1 2.83-2.83l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 1 1 4 0v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 1 1 2.83 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 1 1 0 4h-.09a1.65 1.65 0 0 0-1.51 1z"/></svg>';gear.addEventListener('click',function(){location.href='/user-setting/data-source/'+encodeURIComponent(item.id)});var trash=document.createElement('button');trash.type='button';trash.className='ds-icon-btn ds-trash';trash.title='Delete';trash.innerHTML='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>';trash.addEventListener('click',function(){openDsDelete(item.id,item.name,item.type)});actions.append(document.createTextNode(' '),gear,document.createTextNode(' '),trash);row.append(name,badge,actions);card.appendChild(row)});root.appendChild(card)})})}function openDsDelete(id,name,type){DS_DELETE_ID=id;var info=DS_SOURCE_INFO[type]||{name:type,icon:'🔗'};var box=document.getElementById('dsDeleteBox');box.replaceChildren();var icon=document.createElement('span');icon.className='ds-available-icon';icon.innerHTML=dsIconHtml(info);var label=document.createElement('span');label.textContent=name;box.append(icon,label);document.getElementById('dsDeleteModal').classList.add('show')}function closeDsDelete(){document.getElementById('dsDeleteModal').classList.remove('show')}function confirmDsDelete(){fetch('/api/v1/data_sources/'+DS_DELETE_ID,{method:'DELETE'}).then(function(response){return response.json()}).then(function(data){if(data.code===0){closeDsDelete();loadDs()}else{alert(data.message||'delete failed')}})}window.addEventListener('message',function(event){var payload=event.data;if(!payload||typeof payload!=='object')return;var expected=window.DSC_TYPE==='gmail'?'ragflow-gmail-oauth':'ragflow-google-drive-oauth';if(payload.type!==expected)return;if(!payload.flowId||payload.flowId!==window.DSC_GOOGLE_FLOW)return;if(payload.status==='success'){dscGoogleMsg('Authorization confirmed. Finalizing tokens...',false);dscGooglePoll()}else{dscGoogleMsg(payload.message||'Authorization window reported an error.',true);window.DSC_GOOGLE_FLOW='';var r=document.getElementById('dscGoogleRefresh');if(r)r.hidden=true}});dsRenderCards();loadDs()</script>"#;
    format!("{style}{delete_modal}{}", js.replace("__INFO__", info_json))
}

pub async fn data_source_detail_page(
    State(state): State<Arc<AppState>>,
    axum::extract::Path(id): axum::extract::Path<String>,
    req: axum::http::Request<axum::body::Body>,
) -> axum::response::Response {
    let zh = detect_lang(req.headers());
    let Some(record) = state.data_sources.as_ref().and_then(|store| store.get(&id)) else {
        return Html(layout(
            t("Data source", zh),
            &format!(
                "<h1>404</h1><p>{}: {id}</p>",
                t("Data source not found", zh)
            ),
            zh,
        ))
        .into_response();
    };
    let schema = serde_json::to_string(&crate::data_source::form_fields::schema_for_ui())
        .unwrap_or_else(|_| "{{}}".to_string());
    let body = data_source_detail_body(&record.name, &id, &record.kind, &schema, zh);
    Html(user_setting_layout(
        t("Data source", zh),
        &body,
        UserSettingSection::DataSource,
        zh,
    ))
    .into_response()
}

/// Upstream `pages/files/index.tsx`: `ListFilterBar` (breadcrumb/title + search +
/// the `Add file` dropdown with `Upload file` / `New folder`), the bulk bar
/// (Move / Link to dataset / Delete) once rows are selected, the file table
/// (select-all, Name, Upload date, Size, Dataset, Action) and the pagination
/// footer. The previous revision had a dangling `addFileBtn` listener that
/// threw before `loadF()` ran, leaving the table stuck on "Loading...".
pub async fn files_page(
    State(_state): State<Arc<AppState>>,
    req: axum::http::Request<axum::body::Body>,
) -> impl IntoResponse {
    let zh = detect_lang(req.headers());
    let title_label = if zh { "文件" } else { "Files" };
    let add_file_label = if zh { "新增文件" } else { "Add file" };
    let upload_file_label = if zh { "上传文件" } else { "Upload file" };
    let new_folder_label = if zh { "新建文件夹" } else { "New folder" };
    let search_label = if zh { "搜索" } else { "Search" };
    let name_label = if zh { "名称" } else { "Name" };
    let upload_date_label = if zh { "上传日期" } else { "Upload date" };
    let size_label = if zh { "大小" } else { "Size" };
    let dataset_label = if zh { "知识库" } else { "Dataset" };
    let action_label = if zh { "操作" } else { "Action" };
    let move_label = if zh { "移动" } else { "Move" };
    let link_label = if zh {
        "链接知识库"
    } else {
        "Link to dataset"
    };
    let delete_label = if zh { "删除" } else { "Delete" };
    let rename_label = if zh { "重命名" } else { "Rename" };
    let download_label = if zh { "下载" } else { "Download" };
    let save_label = if zh { "保存" } else { "Save" };
    let cancel_label = if zh { "取消" } else { "Cancel" };
    let close_label = if zh { "关闭" } else { "Close" };
    let total_label = if zh { "总共" } else { "Total" };
    let folder_label = if zh { "文件夹" } else { "Folder" };
    let folder_name_label = if zh { "名称" } else { "Name" };
    let empty_label = if zh { "暂无文件" } else { "No file yet" };
    let selected_label = if zh { "已选择" } else { "Selected" };
    let destination_label = if zh {
        "目标文件夹"
    } else {
        "Destination folder"
    };
    let dataset_id_label = if zh { "知识库 ID" } else { "Dataset ID" };
    let folder_name_required = if zh {
        "名称必填"
    } else {
        "Name is required"
    };

    let mut b = String::with_capacity(16384);
    b.push_str("<article class='list-page' data-testid='files-list'><header class='list-filter-bar'><h1 class='list-title'><span class='list-title-icon' aria-hidden='true'>");
    b.push_str(file_icon_svg());
    b.push_str("</span><span id='fileBreadcrumb'>");
    b.push_str(title_label);
    b.push_str("</span></h1><div class='list-bar-actions'><input id='fileQ' class='list-search' type='search' placeholder='");
    b.push_str(search_label);
    b.push_str("' aria-label='");
    b.push_str(search_label);
    b.push_str("' oninput='fileFilter(this.value)'><div class='menu' id='addFileMenu'><button type='button' class='btn btn-p' id='addFileBtn' aria-haspopup='menu' aria-expanded='false' data-testid='files-add' onclick='toggleHeaderMenu(\"addFileMenu\",event)'><svg width='14' height='14' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='2.2' stroke-linecap='round' aria-hidden='true'><path d='M12 5v14M5 12h14'/></svg>");
    b.push_str(add_file_label);
    b.push_str("</button><div class='menu-panel' role='menu'><button type='button' role='menuitem' class='menu-item' data-testid='files-upload' onclick='afUpload()'>");
    b.push_str(upload_file_label);
    b.push_str("</button><button type='button' role='menuitem' class='menu-item' data-testid='files-new-folder' onclick='afNewFolder()'>");
    b.push_str(new_folder_label);
    b.push_str("</button></div></div></div></header>");
    b.push_str("<input type='file' id='fu' hidden onchange='uploadF()'>");
    b.push_str("<div id='fileBatchBar' class='bulk-bar' hidden data-testid='files-bulk-bar'><span id='fileSelCount' class='bulk-count'></span><button type='button' class='btn btn-o btn-sm' onclick='batchMove()'>");
    b.push_str(move_label);
    b.push_str("</button><button type='button' class='btn btn-o btn-sm' onclick='batchLink()'>");
    b.push_str(link_label);
    b.push_str("</button><button type='button' class='btn btn-d btn-sm' onclick='batchDelete()'>");
    b.push_str(delete_label);
    b.push_str("</button></div>");
    b.push_str("<div class='table-wrap'><table class='file-table' data-testid='files-table'><thead><tr><th class='col-select'><input type='checkbox' id='fileSelAll' aria-label='Select all' onchange='fileSelAll(this.checked)'></th><th>");
    b.push_str(name_label);
    b.push_str("</th><th>");
    b.push_str(upload_date_label);
    b.push_str("</th><th>");
    b.push_str(size_label);
    b.push_str("</th><th>");
    b.push_str(dataset_label);
    b.push_str("</th><th>");
    b.push_str(action_label);
    b.push_str("</th></tr></thead><tbody id='fl'><tr><td colspan='6' class='table-empty'>...</td></tr></tbody></table></div>");
    b.push_str("<footer class='list-pagination' id='filePagination'></footer></article>");

    // New-folder dialog + move/link prompts reuse one small modal each.
    b.push_str("<div class='modal-overlay' id='newFolderModal' data-testid='files-new-folder-dialog' onclick='if(event.target===this)closeNewFolder()'><div class='modal' style='max-width:420px' role='dialog' aria-modal='true' aria-labelledby='newFolderTitle'><h2 id='newFolderTitle' style='margin-top:0'>");
    b.push_str(new_folder_label);
    b.push_str("</h2><label class='ds-field'><span class='ds-field-label required'>");
    b.push_str(folder_name_label);
    b.push_str("</span><input id='folderName' autocomplete='off'><span class='ds-field-error' id='folderNameError'></span></label><div class='ds-dialog-footer'><button type='button' class='btn btn-o' onclick='closeNewFolder()'>");
    b.push_str(cancel_label);
    b.push_str("</button><button type='button' class='btn btn-p' data-testid='files-new-folder-save' onclick='createFolder()'>");
    b.push_str(save_label);
    b.push_str("</button></div></div></div>");
    b.push_str("<div class='modal-overlay' id='moveFileModal' data-testid='files-move-dialog' onclick='if(event.target===this)closeMove()'><div class='modal' style='max-width:420px' role='dialog' aria-modal='true' aria-labelledby='moveFileTitle'><h2 id='moveFileTitle' style='margin-top:0'>");
    b.push_str(move_label);
    b.push_str("</h2><label class='ds-field'><span class='ds-field-label'>");
    b.push_str(destination_label);
    b.push_str("</span><select id='moveTarget'><option value=''>/</option></select></label><div class='ds-dialog-footer'><button type='button' class='btn btn-o' onclick='closeMove()'>");
    b.push_str(cancel_label);
    b.push_str("</button><button type='button' class='btn btn-p' onclick='moveSubmit()'>");
    b.push_str(save_label);
    b.push_str("</button></div></div></div>");
    b.push_str("<div class='modal-overlay' id='linkFileModal' data-testid='files-link-dialog' onclick='if(event.target===this)closeLink()'><div class='modal' style='max-width:420px' role='dialog' aria-modal='true' aria-labelledby='linkFileTitle'><h2 id='linkFileTitle' style='margin-top:0'>");
    b.push_str(link_label);
    b.push_str("</h2><label class='ds-field'><span class='ds-field-label required'>");
    b.push_str(dataset_id_label);
    b.push_str("</span><input id='linkDatasetId' autocomplete='off'></label><div class='ds-dialog-footer'><button type='button' class='btn btn-o' onclick='closeLink()'>");
    b.push_str(cancel_label);
    b.push_str("</button><button type='button' class='btn btn-p' onclick='linkSubmit()'>");
    b.push_str(save_label);
    b.push_str("</button></div></div></div>");

    b.push_str("<script>const FILE_LABELS={delete:");
    b.push_str(&json_script_string(delete_label));
    b.push_str(",rename:");
    b.push_str(&json_script_string(rename_label));
    b.push_str(",download:");
    b.push_str(&json_script_string(download_label));
    b.push_str(",link:");
    b.push_str(&json_script_string(link_label));
    b.push_str(",empty:");
    b.push_str(&json_script_string(empty_label));
    b.push_str(",total:");
    b.push_str(&json_script_string(total_label));
    b.push_str(",selected:");
    b.push_str(&json_script_string(selected_label));
    b.push_str(",folder:");
    b.push_str(&json_script_string(folder_label));
    b.push_str(",folderRequired:");
    b.push_str(&json_script_string(folder_name_required));
    b.push_str("};let fileItems=[];let filePage=1;let filePageSize=50;let fileKeyword='';let filePendingLink=[];function fe(value){return String(value==null?'':value).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\"/g,'&quot;')}function fileFilter(value){fileKeyword=String(value||'').trim().toLowerCase();filePage=1;renderFiles()}function filteredFiles(){if(!fileKeyword)return fileItems;return fileItems.filter(function(item){return String(item.name||'').toLowerCase().indexOf(fileKeyword)>=0})}function fileSize(item){if(item.file_type==='folder')return '-';var bytes=Number(item.size||0);if(bytes>=1048576)return (bytes/1048576).toFixed(1)+' MB';if(bytes>=1024)return (bytes/1024).toFixed(0)+' KB';return bytes+' B'}function fileDate(item){var raw=item.create_time||item.created_at;if(!raw)return '';var value=typeof raw==='number'?raw:Date.parse(raw);if(!value||isNaN(value))return String(raw);return new Date(value).toLocaleDateString()}function fileDataset(item){var kb=item.kb_id||item.dataset_id;return kb?fe(String(kb).slice(0,8)):''}function renderFiles(){var body=document.getElementById('fl');if(!body)return;var list=filteredFiles();if(!list.length){body.innerHTML=\"<tr><td colspan='6' class='table-empty'>\"+FILE_LABELS.empty+\"</td></tr>\";renderFilePagination(0);return}var pages=Math.max(1,Math.ceil(list.length/filePageSize));if(filePage>pages)filePage=pages;var slice=list.slice((filePage-1)*filePageSize,filePage*filePageSize);body.innerHTML=slice.map(function(item){var isFolder=item.file_type==='folder';var actions=\"<button type='button' class='btn btn-o btn-sm' onclick='renameF(\\\"\"+item.id+\"\\\",\\\"\"+fe(item.name)+\"\\\")'>\"+FILE_LABELS.rename+\"</button> <button type='button' class='btn btn-d btn-sm' onclick='delFile(\\\"\"+item.id+\"\\\")'>\"+FILE_LABELS.delete+\"</button>\";if(!isFolder){actions=\"<a class='btn btn-o btn-sm' href='/api/v1/files/\"+item.id+\"/download' target='_blank' rel='noreferrer'>\"+FILE_LABELS.download+\"</a> <button type='button' class='btn btn-o btn-sm' onclick='linkFile(\\\"\"+item.id+\"\\\")'>\"+FILE_LABELS.link+\"</button> \"+actions}return \"<tr data-name=\\\"\"+fe(String(item.name||'').toLowerCase())+\"\\\"><td class='col-select'><input type='checkbox' class='fileCk' value='\"+item.id+\"' onchange='updateFileBatch()'></td><td class='file-name'>\"+(isFolder?'📁 ':'')+fe(item.name)+\"</td><td class='co'>\"+fileDate(item)+\"</td><td class='co'>\"+fileSize(item)+\"</td><td class='co'>\"+fileDataset(item)+\"</td><td class='file-actions'>\"+actions+\"</td></tr>\"}).join('');renderFilePagination(list.length);updateFileBatch()}function renderFilePagination(total){var host=document.getElementById('filePagination');if(!host)return;if(!total){host.innerHTML='';return}var pages=Math.max(1,Math.ceil(total/filePageSize));host.innerHTML=\"<span class='list-total'>\"+FILE_LABELS.total+' '+total+\"</span><span class='list-page-size'><select aria-label='Page size' onchange='filePageSizeChange(this.value)'><option value='50'\"+(filePageSize===50?' selected':'')+\">50</option><option value='20'\"+(filePageSize===20?' selected':'')+\">20</option><option value='100'\"+(filePageSize===100?' selected':'')+\">100</option></select></span><span class='list-pager'><button type='button' class='btn btn-o btn-sm' \"+(filePage<=1?'disabled':'')+\" onclick='fileGoto(filePage-1)'>‹</button><span class='list-page-now'>\"+filePage+' / '+pages+\"</span><button type='button' class='btn btn-o btn-sm' \"+(filePage>=pages?'disabled':'')+\" onclick='fileGoto(filePage+1)'>›</button></span>\"}function fileGoto(page){filePage=page;renderFiles()}function filePageSizeChange(value){filePageSize=parseInt(value,10)||50;filePage=1;renderFiles()}function selFileIds(){var ids=[];document.querySelectorAll('.fileCk:checked').forEach(function(box){ids.push(box.value)});return ids}function updateFileBatch(){var ids=selFileIds();var bar=document.getElementById('fileBatchBar');var count=document.getElementById('fileSelCount');if(count)count.textContent=FILE_LABELS.selected+' '+ids.length;if(bar)bar.hidden=ids.length===0}function fileSelAll(on){document.querySelectorAll('.fileCk').forEach(function(box){box.checked=on});updateFileBatch()}function loadF(){fetch('/api/v1/files').then(function(response){return response.json()}).then(function(data){fileItems=Array.isArray(data.data)?data.data:[];fileFolders();renderFiles()}).catch(function(){})}function fileFolders(){var select=document.getElementById('moveTarget');if(!select)return;var folders=fileItems.filter(function(item){return item.file_type==='folder'});select.innerHTML=\"<option value=''>/</option>\"+folders.map(function(item){return \"<option value='\"+item.id+\"'>\"+fe(item.name)+\"</option>\"}).join('')}function afUpload(){document.getElementById('fu').click()}function afNewFolder(){document.getElementById('folderName').value='';var err=document.getElementById('folderNameError');if(err)err.textContent='';document.getElementById('newFolderModal').classList.add('show')}function closeNewFolder(){document.getElementById('newFolderModal').classList.remove('show')}function createFolder(){var name=document.getElementById('folderName').value.trim();if(!name){document.getElementById('folderNameError').textContent=FILE_LABELS.folderRequired;return}fetch('/api/v1/files/folder',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:name})}).then(function(response){return response.json()}).then(function(data){if(data.code!==0)throw new Error(data.message||'Create folder failed');closeNewFolder();loadF()}).catch(function(error){document.getElementById('folderNameError').textContent=error.message})}function uploadF(){var input=document.getElementById('fu');var file=input.files&&input.files[0];if(!file)return;var form=new FormData();form.append('file',file,file.name);fetch('/api/v1/files/upload',{method:'POST',body:form}).then(function(response){return response.json()}).then(function(data){if(data.code!==0)throw new Error(data.message||'Upload failed');input.value='';loadF()}).catch(function(error){alert(error.message)})}function renameF(id,current){var next=prompt(FILE_LABELS.rename,current);if(!next||next===current)return;fetch('/api/v1/files/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:next})}).then(function(response){return response.json()}).then(function(data){if(data.code!==0)throw new Error(data.message||'Rename failed');loadF()}).catch(function(error){alert(error.message)})}function delFile(id){if(!confirm(FILE_LABELS.delete+'?'))return;fetch('/api/v1/files/'+id,{method:'DELETE'}).then(function(response){return response.json()}).then(function(data){if(data.code!==0)throw new Error(data.message||'Delete failed');loadF()}).catch(function(error){alert(error.message)})}function batchDelete(){var ids=selFileIds();if(!ids.length)return;if(!confirm(FILE_LABELS.delete+' '+ids.length+'?'))return;var index=0;function next(){if(index>=ids.length){loadF();return}var id=ids[index++];fetch('/api/v1/files/'+id,{method:'DELETE'}).then(function(){next()}).catch(function(){next()})}next()}function batchMove(){var ids=selFileIds();if(!ids.length)return;filePendingLink=[];document.getElementById('moveFileModal').classList.add('show');window.__moveIds=ids}function closeMove(){document.getElementById('moveFileModal').classList.remove('show')}function moveSubmit(){var ids=window.__moveIds||[];var target=document.getElementById('moveTarget').value;if(!ids.length)return;Promise.all(ids.map(function(id){return fetch('/api/v1/files/'+id,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({parent_id:target})})})).then(function(){closeMove();loadF()}).catch(function(error){alert(error.message)})}function linkFile(id){filePendingLink=[id];document.getElementById('linkDatasetId').value='';document.getElementById('linkFileModal').classList.add('show')}function batchLink(){var ids=selFileIds();if(!ids.length)return;filePendingLink=ids;document.getElementById('linkDatasetId').value='';document.getElementById('linkFileModal').classList.add('show')}function closeLink(){document.getElementById('linkFileModal').classList.remove('show')}function linkSubmit(){var dataset=document.getElementById('linkDatasetId').value.trim();if(!dataset||!filePendingLink.length)return;fetch('/api/v1/file2document',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({file_ids:filePendingLink,dataset_id:dataset})}).then(function(response){return response.json()}).then(function(data){if(data.code!==0)throw new Error(data.message||'Link failed');closeLink();loadF()}).catch(function(error){alert(error.message)})}loadF()</script>");
    Html(layout(title_label, &b, zh))
}

fn file_icon_svg() -> &'static str {
    "<svg width='24' height='24' viewBox='0 0 24 24' fill='none' stroke='currentColor' stroke-width='1.6' stroke-linecap='round' stroke-linejoin='round' aria-hidden='true'><path d='M14 3v5h5'/><path d='M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h9l5 5v11a2 2 0 0 1-2 2Z'/></svg>"
}
pub async fn memories_page(
    State(state): State<Arc<AppState>>,
    req: axum::http::Request<axum::body::Body>,
) -> impl IntoResponse {
    let zh = detect_lang(req.headers());
    let convs = state.conversations.list();
    let mut b = String::new();
    b.push_str("<h1>🧠 ");
    b.push_str(t("Memories", zh));
    b.push_str("</h1><div style='display:flex;align-items:center;gap:12px;margin-bottom:16px'><button class='btn btn-p' onclick='showMemModal()'>+ ");
    b.push_str(t("Create Memory", zh));
    b.push_str("</button><button class='btn btn-d' onclick='clearAllMem()'>🗑 ");
    b.push_str(t("Clear All", zh));
    b.push_str("</button></div><div class='card'><h2>Memory Apps <span style='font-size:12px;color:var(--tm)' id='memCount'></span></h2><div id='memList'>Loading...</div></div>");
    // Add / edit memory modal (RAGFlow memory fields: name / memory_type / embd / llm)
    b.push_str(
        "<div class='modal-overlay' id='memModal'><div class='modal'><h2 id='memModalTitle'>",
    );
    b.push_str(t("Create Memory", zh));
    b.push_str("</h2><input id='mname' placeholder='Name'><label style='font-size:12px;display:block;margin:8px 0 4px'>Memory Type</label><div style='font-size:12px;margin-bottom:4px'><a href='javascript:void(0)' onclick=\"document.querySelectorAll('.mtype').forEach(function(x){x.checked=true})\" style='color:var(--p)'>Select all</a></div><div style='display:flex;gap:10px;flex-wrap:wrap;font-size:12px'><label><input type='checkbox' class='mtype' value='raw'> raw</label><label><input type='checkbox' class='mtype' value='semantic'> semantic</label><label><input type='checkbox' class='mtype' value='episodic'> episodic</label><label><input type='checkbox' class='mtype' value='procedural'> procedural</label></div><label style='font-size:12px;display:block;margin:8px 0 4px'>Embedding Model</label><select id='membd'><option value='default'>default</option></select><label style='font-size:12px;display:block;margin:8px 0 4px'>Chat Model</label><select id='mllm'><option value='default'>default</option></select><textarea id='mdesc' placeholder='Description' style='margin-top:8px;min-height:50px'></textarea><div style='display:flex;gap:8px;margin-top:16px'><button class='btn btn-p' onclick='saveMem()'>");
    b.push_str(t("Save", zh));
    b.push_str("</button><button class='btn btn-o' onclick='closeMemModal()'>");
    b.push_str(t("Cancel", zh));
    b.push_str("</button></div></div></div>");
    b.push_str("<script>var memEditId=null;function showMemModal(){memEditId=null;document.getElementById('mname').value='';document.getElementById('mdesc').value='';document.querySelectorAll('.mtype').forEach(function(x){x.checked=false});document.getElementById('memModalTitle').textContent='Create Memory';document.getElementById('memModal').classList.add('show')};function closeMemModal(){document.getElementById('memModal').classList.remove('show')};function editMem(m){memEditId=m.id;document.getElementById('mname').value=m.name||'';document.getElementById('mdesc').value=m.description||'';document.querySelectorAll('.mtype').forEach(function(x){x.checked=(m.memory_type||[]).indexOf(x.value)>=0});if(m.embd_id)document.getElementById('membd').value=m.embd_id;if(m.llm_id)document.getElementById('mllm').value=m.llm_id;document.getElementById('memModalTitle').textContent='Edit Memory';document.getElementById('memModal').classList.add('show')};function saveMem(){var n=document.getElementById('mname').value;if(!n){alert('Name required');return}var types=[];document.querySelectorAll('.mtype:checked').forEach(function(x){types.push(x.value)});if(!types.length){types=['raw']}var body={name:n,memory_type:types,embd_id:document.getElementById('membd').value||'default',llm_id:document.getElementById('mllm').value||'default',description:document.getElementById('mdesc').value};var url=memEditId?'/api/v1/memories/'+memEditId:'/api/v1/memories';var method=memEditId?'PUT':'POST';fetch(url,{method:method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json()).then(d=>{if(d.code===0){closeMemModal();loadMems()}else{alert(d.message||'Save failed')}})};function delMem(id){if(!confirm('Delete this memory?'))return;fetch('/api/v1/memories/'+id,{method:'DELETE'}).then(r=>r.json()).then(d=>{if(d.code===0){loadMems()}else{alert(d.message||'Delete failed')}})};function clearAllMem(){if(!confirm('Delete ALL memories?'))return;fetch('/api/v1/memories/clear',{method:'DELETE'}).then(r=>r.json()).then(d=>{if(d.code===0){loadMems()}else{alert(d.message||'Clear failed')}})};function loadMems(){fetch('/api/v1/memories').then(r=>r.json()).then(d=>{var list=(d.data&&d.data.memory_list)||[];document.getElementById('memCount').textContent='('+list.length+')';var h='<table><thead><tr><th>Name</th><th>Type</th><th>Storage</th><th>Embedding</th><th>Chat</th><th>Size</th><th></th></tr></thead><tbody>';list.forEach(function(m){h+='<tr><td style=font-weight:500>'+(m.name||'')+'</td><td>'+(m.memory_type||[]).join(', ')+'</td><td class=co>'+(m.storage_type||'')+'</td><td class=co>'+(m.embd_id||'')+'</td><td class=co>'+(m.llm_id||'')+'</td><td>'+(m.memory_size||0)+'</td><td><button class=btn btn-o btn-sm onclick=\\'editMem('+JSON.stringify(m).replace(/'/g,'&#39;')+')\\' style=\\'font-size:12px\\'>✏️ Edit</button> <button class=btn btn-d btn-sm onclick=\\'delMem(\\\"'+m.id+'\\\")\\'>Del</button></td></tr>'});document.getElementById('memList').innerHTML=h+'</tbody></table>'||'<p style=color:var(--tm);padding:20px>No memories yet.</p>'})};function loadModelOpts(){fetch('/api/v1/providers').then(r=>r.json()).then(function(d){var ps=d.data||[];var e=document.getElementById('membd');var l=document.getElementById('mllm');(ps||[]).forEach(function(p){if(!p.models)return;(p.models||[]).forEach(function(m){var o=document.createElement('option');o.value=p.id+':'+m;o.textContent=m;e.appendChild(o);var o2=document.createElement('option');o2.value=p.id+':'+m;o2.textContent=m;l.appendChild(o2)})})}).catch(function(){})};loadMems();loadModelOpts();</script>");
    // Keep conversation list below for reference (RAGFlow memory page also links sessions)
    if !convs.is_empty() {
        let mut rows = String::new();
        for c in convs.iter().rev().take(10) {
            let msgs = c.messages.len();
            rows.push_str(&format!("<tr><td style='font-weight:500'>{}</td><td>{} msgs</td><td><a class='btn btn-o btn-sm' href='/chat/{}'>View</a></td></tr>", c.name.chars().take(40).collect::<String>(), msgs, c.id));
        }
        b.push_str("<div class='card' style='margin-top:16px'><h2>Recent Conversations</h2><table><thead><tr><th>Name</th><th>Messages</th><th></th></tr></thead><tbody>");
        b.push_str(&rows);
        b.push_str("</tbody></table></div>");
    }
    Html(layout(t("Memories", zh), &b, zh))
}

/// Fixed-version Memory card surface. Business data is deliberately loaded
/// through authenticated APIs rather than embedded in this public HTML shell.
/// Upstream `pages/memories/index.tsx`: same list composition as the other
/// application pages, with the `memories.*` labels, the memory type/model
/// fields of `add-or-edit-modal.tsx` (`createMemoryFields`) and the
/// `deleteModal.delMemory` confirm whose content carries `delMemoryWarn`.
pub async fn memories_page_v2(req: axum::http::Request<axum::body::Body>) -> impl IntoResponse {
    let zh = detect_lang(req.headers());
    let memory_type_label = if zh { "记忆类型" } else { "Memory type" };
    let embedding_label = if zh {
        "嵌入模型"
    } else {
        "Embedding model"
    };
    let llm_label = if zh { "大语言模型" } else { "LLM" };
    let raw_label = "Raw";
    let semantic_label = "Semantic";
    let episodic_label = "Episodic";
    let procedural_label = "Procedural";
    let type_tooltip = if zh {
        "Raw 记忆保留原始对话，是其它记忆类型的基础。"
    } else {
        "Raw memory keeps the original dialogue and is the base of every other type."
    };

    let mut form_extra = String::new();
    form_extra.push_str("<div class='ds-field'><span class='ds-field-label required'>");
    form_extra.push_str(memory_type_label);
    form_extra.push_str(" <span class='tip' data-tip='");
    form_extra.push_str(type_tooltip);
    form_extra.push_str("'>?</span></span><div class='lp-memory-types'>");
    for (value, label, checked, disabled) in [
        ("raw", raw_label, true, true),
        ("semantic", semantic_label, false, false),
        ("episodic", episodic_label, false, false),
        ("procedural", procedural_label, false, false),
    ] {
        form_extra.push_str(
            "<label class='ds-radio'><input type='checkbox' class='lp-memory-type' value='",
        );
        form_extra.push_str(value);
        form_extra.push('\'');
        if checked {
            form_extra.push_str(" checked");
        }
        if disabled {
            form_extra.push_str(" disabled");
        }
        form_extra.push_str("> <span>");
        form_extra.push_str(label);
        form_extra.push_str("</span></label>");
    }
    form_extra.push_str("</div><span class='ds-field-error' id='lpMemoryTypeError'></span></div>");
    form_extra.push_str("<div class='ds-field'><span class='ds-field-label required'>");
    form_extra.push_str(embedding_label);
    form_extra.push_str("</span>");
    push_default_model_selector(&mut form_extra, &MEMORY_LIST_EMBD_SELECTOR_FIELD, zh);
    form_extra.push_str("</div><div class='ds-field'><span class='ds-field-label required'>");
    form_extra.push_str(llm_label);
    form_extra.push_str("</span>");
    push_default_model_selector(&mut form_extra, &MEMORY_LIST_LLM_SELECTOR_FIELD, zh);
    form_extra.push_str("</div>");

    let mut page_script = String::new();
    page_script.push_str("<script>const MODEL_FIELDS=");
    page_script.push_str(&json_script_value(&serde_json::json!([
        {
            "fieldId": MEMORY_LIST_EMBD_SELECTOR_FIELD.field_id,
            "domId": MEMORY_LIST_EMBD_SELECTOR_FIELD.dom_id,
            "updateType": MEMORY_LIST_EMBD_SELECTOR_FIELD.update_type,
            "responseType": MEMORY_LIST_EMBD_SELECTOR_FIELD.response_type,
            "acceptedTypes": MEMORY_LIST_EMBD_SELECTOR_FIELD.accepted_types,
            "required": MEMORY_LIST_EMBD_SELECTOR_FIELD.required,
            "placeholder": MEMORY_LIST_EMBD_SELECTOR_FIELD.placeholder,
        },
        {
            "fieldId": MEMORY_LIST_LLM_SELECTOR_FIELD.field_id,
            "domId": MEMORY_LIST_LLM_SELECTOR_FIELD.dom_id,
            "updateType": MEMORY_LIST_LLM_SELECTOR_FIELD.update_type,
            "responseType": MEMORY_LIST_LLM_SELECTOR_FIELD.response_type,
            "acceptedTypes": MEMORY_LIST_LLM_SELECTOR_FIELD.accepted_types,
            "required": MEMORY_LIST_LLM_SELECTOR_FIELD.required,
            "placeholder": MEMORY_LIST_LLM_SELECTOR_FIELD.placeholder,
        }
    ])));
    page_script.push_str(DEFAULT_MODEL_TREE_JS_HEAD);
    page_script.push_str(DEFAULT_MODEL_TREE_JS_BODY);
    page_script.push_str(FORM_LOCAL_SAVE_MODEL_DEFAULT);
    page_script.push_str("function lpMemoryTypes(){var values=[];document.querySelectorAll('.lp-memory-type:checked').forEach(function(box){values.push(box.value)});if(values.indexOf('raw')<0)values.unshift('raw');return values}function lpModelValue(id){var trigger=document.getElementById(id);return trigger?(trigger.dataset.value||''):''}function lpExtraPayload(){return {memory_type:lpMemoryTypes(),embd_id:lpModelValue('memListEmbd')||'default',llm_id:lpModelValue('memListLlm')||'default'}}async function lpSeedMemoryDefaults(){try{var response=await fetch('/api/v1/models/default');var data=await response.json();if(!response.ok||data.code!==0)return;var models=(data.data&&data.data.models)||[];[[\"memListEmbd\",\"embedding\"],[\"memListLlm\",\"chat\"]].forEach(function(pair){var trigger=document.getElementById(pair[0]);if(!trigger||trigger.dataset.value)return;var found=models.find(function(model){return String(model.model_type)===pair[1]});if(!found)return;trigger.dataset.value=found.selector||'';trigger.dataset.savedValue=found.selector||'';renderDefaultModelTrigger(modelField(pair[1]==='chat'?'llm_id':'embd_id'))})}catch(error){}}async function lpLoadModelCatalog(){try{var response=await fetch('/api/v1/models');var data=await response.json();if(!response.ok||data.code!==0)return;DEFAULT_MODEL_CATALOG=(data.data||[]).map(normalizeDefaultModel).filter(function(model){return model.selector});MODEL_FIELDS.forEach(function(field){var state=defaultModelState(field);state.expanded.clear();expandDefaultModelTree(field);renderDefaultModelTrigger(field);renderDefaultModelTree(field)});await lpSeedMemoryDefaults()}catch(error){}}lpLoadModelCatalog()</script>");

    let spec = AppListSpec {
        testid: "memory-list",
        create_testid: "create-memory",
        empty_testid: "memory-empty",
        title: if zh { "记忆" } else { "Memory" }.to_string(),
        create_label: if zh { "创建记忆" } else { "Create memory" }.to_string(),
        delete_title: if zh { "删除记忆" } else { "Delete memory" }.to_string(),
        empty_label: if zh {
            "尚未创建记忆"
        } else {
            "No memory created yet"
        }
        .to_string(),
        search_placeholder: if zh { "搜索" } else { "Search" }.to_string(),
        list_url: "/api/v1/memories",
        collection: "memory_list",
        rename_method: "PUT",
        detail_prefix: "/memory/",
        empty_href: "/memories?isCreate=true",
        meta: "types",
        icon: memory_icon(),
        create_menu: false,
        templates_href: "",
        extra_menu_label: String::new(),
        flow_types: None,
        import_url: "",
        form_extra,
        page_script,
    };
    Html(render_app_list_page(&spec, zh))
}

