pub async fn login_page(req: axum::http::Request<axum::body::Body>) -> impl IntoResponse {
    let zh = detect_lang(req.headers());
    let login_title = if zh { "登录" } else { "Sign in" };
    let register_title = if zh { "注册" } else { "Sign up" };
    let email_label = if zh { "邮箱" } else { "Email" };
    let password_label = if zh { "密码" } else { "Password" };
    let nickname_label = if zh { "昵称" } else { "Nickname" };
    let remember_label = if zh { "记住我" } else { "Remember me" };
    let sign_in_tip = if zh {
        "还没有账号？"
    } else {
        "Don’t have an account?"
    };
    let sign_up_tip = if zh {
        "已有账号？"
    } else {
        "Already have an account?"
    };
    let login_button = if zh { "登录" } else { "Sign in" };
    let register_button = if zh { "继续" } else { "Continue" };
    let mut b = String::with_capacity(4096);
    // Upstream `login-next/card.tsx` FlipCard3D: two faces inside a 3D scene,
    // the active one carrying `data-testid='auth-card-active'`.
    // Upstream `login-next/bg.tsx` (BgSvg) + three `Spotlight` overlays sit
    // behind the flip card; both are decorative (aria-hidden, pointer-events
    // none) and animate with the fixed 16s dash flow.
    b.push_str(LOGIN_BG_SVG);
    b.push_str("<div class='auth-scene'><div class='auth-stage' id='authStage'><div class='auth-face auth-face-front' id='authLoginFace' data-testid='auth-card-active'><div class='auth-card card'><div class='auth-heading'><h2 id='authTitle'>");
    b.push_str(if zh {
        "登录你的账号"
    } else {
        "Sign in to your account"
    });
    b.push_str("</h2></div><form class='auth-form' id='loginForm' data-testid='auth-form' data-active='true' onsubmit='event.preventDefault();login()'><label class='auth-field'><span class='auth-label required'>");
    b.push_str(email_label);
    b.push_str("</span><input id='email' data-testid='auth-email' placeholder='");
    b.push_str(if zh {
        "请输入邮箱"
    } else {
        "Please input email"
    });
    b.push_str("' autocomplete='email'></label><label class='auth-field'><span class='auth-label required'>");
    b.push_str(password_label);
    b.push_str(
        "</span><input id='password' data-testid='auth-password' type='password' placeholder='",
    );
    b.push_str(if zh {
        "请输入密码"
    } else {
        "Please input password"
    });
    b.push_str("' autocomplete='current-password'></label><label class='auth-remember'><input id='remember' type='checkbox'> <span>");
    b.push_str(remember_label);
    b.push_str("</span></label><button class='btn btn-p auth-submit' type='submit' data-testid='auth-submit'>");
    b.push_str(login_button);
    b.push_str("</button></form><div id='authChannels' class='auth-channels' hidden></div><div class='auth-switch' id='authSwitchToRegister'><span>");
    b.push_str(sign_in_tip);
    b.push_str("</span> <button type='button' class='auth-link' data-testid='auth-toggle-register' onclick='toggleAuth()'>");
    b.push_str(register_title);
    b.push_str("</button></div></div></div><div class='auth-face auth-face-back' id='authRegisterFace'><div class='auth-card card'><div class='auth-heading'><h2>");
    b.push_str(if zh {
        "创建账号"
    } else {
        "Create an account"
    });
    b.push_str("</h2></div><form class='auth-form' id='regForm' data-testid='auth-form' data-active='false' onsubmit='event.preventDefault();register()'><label class='auth-field'><span class='auth-label required'>");
    b.push_str(email_label);
    b.push_str("</span><input id='remail' data-testid='auth-email' placeholder='");
    b.push_str(if zh {
        "请输入邮箱"
    } else {
        "Please input email"
    });
    b.push_str("' autocomplete='email'></label><label class='auth-field'><span class='auth-label required'>");
    b.push_str(nickname_label);
    b.push_str("</span><input id='nickname' data-testid='auth-nickname' placeholder='");
    b.push_str(if zh {
        "请输入昵称"
    } else {
        "Please input nickname"
    });
    b.push_str("' autocomplete='username'></label><label class='auth-field'><span class='auth-label required'>");
    b.push_str(password_label);
    b.push_str(
        "</span><input id='rpassword' data-testid='auth-password' type='password' placeholder='",
    );
    b.push_str(if zh {
        "请输入密码"
    } else {
        "Please input password"
    });
    b.push_str("' autocomplete='new-password'></label><button class='btn btn-p auth-submit' type='submit' data-testid='auth-submit'>");
    b.push_str(register_button);
    b.push_str("</button></form><div class='auth-switch' id='authSwitchToLogin'><span>");
    b.push_str(sign_up_tip);
    b.push_str("</span> <button type='button' class='auth-link' data-testid='auth-toggle-login' onclick='toggleAuth()'>");
    b.push_str(login_title);
    b.push_str("</button></div></div></div></div></div><div id='error' class='auth-error' role='alert'></div>");
    b.push_str("<script>var authFlipped=false;function setActiveFace(login){var stage=document.getElementById('authStage');var front=document.getElementById('authLoginFace');var back=document.getElementById('authRegisterFace');stage.classList.toggle('flipped',!login);front.toggleAttribute('data-testid',login);back.toggleAttribute('data-testid',!login);if(login){front.setAttribute('data-testid','auth-card-active');back.removeAttribute('data-testid')}else{back.setAttribute('data-testid','auth-card-active');front.removeAttribute('data-testid')}document.getElementById('loginForm').dataset.active=login?'true':'false';document.getElementById('regForm').dataset.active=login?'false':'true'}var AUTH_REGISTER_ENABLED=true;var AUTH_PASSWORD_LOGIN_DISABLED=false;function authRegisterEnabled(){return AUTH_REGISTER_ENABLED!==false}function authPasswordLoginDisabled(){return AUTH_PASSWORD_LOGIN_DISABLED===true}function applyAuthSystemConfig(config){config=config||{};AUTH_REGISTER_ENABLED=config.registerEnabled!==0;AUTH_PASSWORD_LOGIN_DISABLED=config.disablePasswordLogin===true;var switchRegister=document.getElementById('authSwitchToRegister');if(switchRegister)switchRegister.hidden=authPasswordLoginDisabled()||!authRegisterEnabled();var switchLogin=document.getElementById('authSwitchToLogin');if(switchLogin)switchLogin.hidden=authPasswordLoginDisabled();var loginForm=document.getElementById('loginForm');if(loginForm)loginForm.hidden=authPasswordLoginDisabled();var regForm=document.getElementById('regForm');if(regForm)regForm.hidden=authPasswordLoginDisabled();var channels=document.getElementById('authChannels');if(channels)channels.classList.toggle('auth-channels-solo',authPasswordLoginDisabled());if(authPasswordLoginDisabled()){var title=document.getElementById('authTitle');if(title)title.hidden=true}if((authPasswordLoginDisabled()||!authRegisterEnabled())&&authFlipped){authFlipped=false;setTimeout(function(){setActiveFace(true)},200)}}function loadAuthSystemConfig(){fetch('/api/v1/system/config').then(function(response){return response.json()}).then(function(data){applyAuthSystemConfig((data&&data.data)||{})}).catch(function(){})}function toggleAuth(){if(!authFlipped&&(authPasswordLoginDisabled()||!authRegisterEnabled()))return;authFlipped=!authFlipped;setTimeout(function(){setActiveFace(!authFlipped)},200)}
if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',loadAuthSystemConfig)}else{loadAuthSystemConfig()}function setTok(t,remember){localStorage.setItem('rayrag_token',t);document.cookie='rayrag_token='+t+';path=/;max-age=86400';if(remember){localStorage.setItem('rayrag_email',document.getElementById('email').value.trim())}else{localStorage.removeItem('rayrag_email')}}function login(){var e=document.getElementById('email').value;var p=document.getElementById('password').value;var r=document.getElementById('remember').checked;fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:e,password:p,remember:r})}).then(function(response){return response.json()}).then(function(d){if(d.code===0){setTok(d.data.access_token,r);location.href='/'}else{document.getElementById('error').textContent=d.message}}).catch(function(error){document.getElementById('error').textContent=error.message})}function register(){var n=document.getElementById('nickname').value.trim();var e=document.getElementById('remail').value.trim();var p=document.getElementById('rpassword').value;if(!n){document.getElementById('error').textContent='Please input nickname';return}fetch('/api/v1/user/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nickname:n,email:e,password:p})}).then(function(response){return response.json()}).then(function(d){if(d.code===0){return fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:e,password:p})}).then(function(r2){return r2.json()}).then(function(l){if(l.code===0){setTok(l.data.access_token,false);location.href='/'}else{document.getElementById('error').textContent=l.message}})}document.getElementById('error').textContent=d.message})}function loginWithChannel(channel){if(!channel)return;location.href='/api/v1/auth/login/'+encodeURIComponent(channel)}
function loadAuthChannels(){fetch('/api/v1/auth/login/channels').then(function(response){return response.json()}).then(function(d){var list=(d.data||[]);var host=document.getElementById('authChannels');if(!host||!list.length)return;host.hidden=false;host.innerHTML=list.map(function(item){return \"<button type=\\'button\\' class=\\'btn btn-o auth-channel auth-channel-btn\\' data-channel=\\'\"+(item.channel||'')+\"\\'>Sign in with \"+(item.display_name||item.channel)+'</button>'}).join('');Array.prototype.forEach.call(host.querySelectorAll('.auth-channel-btn'),function(button){button.addEventListener('click',function(){loginWithChannel(button.dataset.channel)})})}).catch(function(){})}(function(){var saved=localStorage.getItem('rayrag_email');if(saved){document.getElementById('email').value=saved;document.getElementById('remember').checked=true}})();loadAuthChannels()</script>");
    Html(layout_plain(if zh { "登录" } else { "Sign in" }, &b, zh))
}

/// Shared body of the document viewer, used by both `/documents/{kb}/{doc}`
/// and upstream's standalone `Routes.Document = /document/:id`.
fn document_view_markup(kb_id: &str, doc_id: &str, zh: bool) -> String {
    let mut b = String::new();
    b.push_str("<div style='display:flex;align-items:center;gap:12px;flex-wrap:wrap'><a class='btn btn-o' href='/dataset/");
    b.push_str(&kb_id);
    b.push_str("'>← ");
    b.push_str(t("Back to Dataset", zh));
    b.push_str("</a><h1 style='margin:0;flex:1' id='docTitle'>📄 ...</h1><button class='btn btn-o' onclick='reparse()'>");
    b.push_str(t("Reparse", zh));
    b.push_str("</button><button class='btn btn-d' onclick='delDoc()'>");
    b.push_str(t("Delete", zh));
    b.push_str("</button><button class='btn btn-o' onclick='exportChunks()'>⬇ ");
    b.push_str(t("Export", zh));
    b.push_str("</button></div>");
    b.push_str("<div class='modal-overlay' id='chunkModal'><div class='modal' style='max-width:700px'><h2>");
    b.push_str(t("Edit Chunk", zh));
    b.push_str("</h2><textarea id='chunkContent' style='min-height:200px;width:100%'></textarea><div style='display:flex;gap:8px;margin-top:16px'><button class='btn btn-p' onclick='saveChunk()'>");
    b.push_str(t("Save", zh));
    b.push_str("</button><button class='btn btn-o' onclick='document.getElementById(\"chunkModal\").classList.remove(\"show\")'>");
    b.push_str(t("Cancel", zh));
    b.push_str("</button></div></div></div>");
    b.push_str("<div class='st' style='margin-top:16px'><div class='sc'><span class='lbl'>");
    b.push_str(t("Chunks", zh));
    b.push_str("</span><span class='val' id='docChunks'>-</span></div><div class='sc'><span class='lbl'>Status</span><span class='val' id='docStatus' style='font-size:15px'>-</span></div></div>");
    b.push_str("<div class='card'><h2>");
    b.push_str(t("Chunks", zh));
    b.push_str(
        " <span id='cTotal' style='font-size:13px;color:var(--tm)'></span></h2><div id='cl'>",
    );
    b.push_str(t("Loading...", zh));
    b.push_str("</div></div>");
    b.push_str("<script>var kbId='");
    b.push_str(&kb_id);
    b.push_str("';var docId='");
    b.push_str(&doc_id);
    b.push_str("';function chunkPage(d){window.cPage+=d;loadChunks()};function loadChunks(){fetch('/api/v1/datasets/'+kbId+'/documents/'+docId+'/chunks').then(r=>r.json()).then(d=>{var data=d.data||{};var chunks=data.chunks||[];var doc=data.doc||{};if(doc.name)document.getElementById('docTitle').textContent='📄 '+doc.name;if(doc.run)document.getElementById('docStatus').textContent=doc.run;document.getElementById('docChunks').textContent=chunks.length;document.getElementById('cTotal').textContent='('+chunks.length+')';var h='';window.cPage=0;window.cPageSize=20;var pageData=chunks;function renderPage(){var h='';var start=window.cPage*window.cPageSize;var end=Math.min(start+window.cPageSize,pageData.length);pageData.slice(start,end).forEach(function(c,i){h+=\"<div class='ri'><span class='rs'>#\"+(start+i+1)+\" &middot; pos \"+(c.position||0)+\" &middot; \"+(c.token_count||0)+\" tok</span><div class='rc' style='white-space:pre-wrap'>\"+(c.content||'').substring(0,800)+\"</div><button class='btn btn-o btn-sm' style='margin-top:6px' onclick=\"editChunk('\"+c.id+'\"','\"+(c.content||'').substring(0,2000).replace(/\'/g,'')+'\"')\">Edit</button></div>\"});var pn='<div style=margin-top:12px>';if(window.cPage>0)pn+='<button class=btn btn-o btn-sm onclick=chunkPage(-1)>← Prev</button> ';pn+='<span style=color:var(--tm);font-size:12px> Page '+(window.cPage+1)+' / '+Math.max(1,Math.ceil(pageData.length/window.cPageSize))+' ('+pageData.length+' chunks) </span>';if(end<pageData.length)pn+='<button class=btn btn-o btn-sm onclick=chunkPage(1)>Next →</button>';pn+='</div>';h+=pn;document.getElementById('cl').innerHTML=h||'<p style=color:var(--tm);text-align:center;padding:40px>No chunks</p>'})};var editingChunk='';function editChunk(cid,content){editingChunk=cid;document.getElementById('chunkContent').value=content;document.getElementById('chunkModal').classList.add('show')};function saveChunk(){var content=document.getElementById('chunkContent').value;fetch('/api/v1/datasets/'+kbId+'/documents/'+docId+'/chunks/'+editingChunk,{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:content})}).then(function(r){return r.json()}).then(function(d){document.getElementById('chunkModal').classList.remove('show');if(d.code===0){location.reload()}else{alert('Error: '+(d.message||'unknown'))}})};function reparse(){if(!confirm('Reparse this document?'))return;fetch('/api/v1/datasets/'+kbId+'/documents/'+docId+'/reparse',{method:'POST'}).then(()=>location.reload())};function delDoc(){if(!confirm('Delete this document?'))return;fetch('/api/v1/datasets/'+kbId+'/documents/'+docId,{method:'DELETE'}).then(()=>location.href='/dataset/'+kbId)};function exportChunks(){fetch('/api/v1/datasets/'+kbId+'/documents/'+docId+'/chunks').then(r=>r.json()).then(function(d){var data=d.data||{};var chunks=data.chunks||[];var a=document.createElement('a');a.href='data:application/json;charset=utf-8,'+encodeURIComponent(JSON.stringify(chunks,null,2));a.download='doc_'+docId+'_chunks.json';a.click()})};loadChunks()</script>");
    b
}

pub async fn document_page(
    State(_state): State<Arc<AppState>>,
    axum::extract::Path((kb_id, doc_id)): axum::extract::Path<(String, String)>,
    req: axum::http::Request<axum::body::Body>,
) -> impl IntoResponse {
    let zh = detect_lang(req.headers());
    Html(layout(
        "Document",
        &document_view_markup(&kb_id, &doc_id, zh),
        zh,
    ))
}

/// Upstream `Routes.Document = /document/:id` (standalone document viewer, no
/// layout). The knowledge base is resolved from the document record, so the
/// page renders at the upstream path instead of redirecting.
pub async fn document_viewer_page(
    State(state): State<Arc<AppState>>,
    axum::extract::Path(doc_id): axum::extract::Path<String>,
    req: axum::http::Request<axum::body::Body>,
) -> axum::response::Response {
    let zh = detect_lang(req.headers());
    match state.docs.get(&doc_id) {
        Some(doc) => Html(layout(
            "Document",
            &document_view_markup(&doc.kb_id, &doc_id, zh),
            zh,
        ))
        .into_response(),
        // Unknown document: render the shared 404 page with a real 404 status
        // (the fallback service does the same for unrouted paths).
        None => (axum::http::StatusCode::NOT_FOUND, not_found_page(req).await).into_response(),
    }
}

pub async fn skills_page(
    State(_state): State<Arc<AppState>>,
    req: axum::http::Request<axum::body::Body>,
) -> impl IntoResponse {
    let zh = detect_lang(req.headers());
    let mut b = String::new();
    b.push_str("<h1>");
    b.push_str(t("Skills", zh));
    b.push_str("</h1><p style='color:var(--tm)'>");
    b.push_str(t(
        "Index and search reusable skills by name, tags, description, and content.",
        zh,
    ));
    b.push_str("</p><div class='toolbar' style='display:flex;gap:8px;flex-wrap:wrap;align-items:center'><input id='skillSpace' value='default' placeholder='Space ID' style='max-width:180px'><input id='skillQuery' placeholder='Search skills by meaning...' style='min-width:260px;flex:1' onkeydown='if(event.key===&quot;Enter&quot;)searchSkills()'><button class='btn btn-p' onclick='searchSkills()'>Search</button><button class='btn btn-o' onclick='openSkillModal()'>+ Add Skill</button><button class='btn btn-o' onclick='openSkillConfig()'>⚙ Configure Search</button><button class='btn btn-o' onclick='reindexSkills()'>↻ Reindex All</button></div><p id='skillMeta' style='color:var(--tm);font-size:12px'></p><div id='skillList' class='kb-grid'><p style='color:var(--tm)'>Loading...</p></div>");
    b.push_str("<div class='modal-overlay' id='skillModal'><div class='modal' style='max-width:680px'><h2>Add Skill</h2><label>Skill ID</label><input id='skillId' placeholder='my-skill'><label>Name</label><input id='skillName' placeholder='My Skill'><label>Folder ID</label><input id='skillFolder' placeholder='optional folder id'><label>Version</label><input id='skillVersion' value='1.0.0'><label>Tags</label><input id='skillTags' placeholder='rag, rust, search'><label>Description</label><textarea id='skillDescription'></textarea><label>Content</label><textarea id='skillContent' style='min-height:160px'></textarea><div style='display:flex;gap:8px;margin-top:16px'><button class='btn btn-p' onclick='indexSkill()'>Index</button><button class='btn btn-o' onclick='closeSkillModal()'>Cancel</button></div></div></div>");
    b.push_str("<div class='modal-overlay' id='skillConfigModal'><div class='modal' style='max-width:620px'><h2>");
    b.push_str(t("Skill Search Configuration", zh));
    b.push_str("</h2><p class='user-setting-description' style='margin:0 0 12px'>");
    b.push_str(t("Configure how skills are indexed and searched", zh));
    b.push_str("</p><label>");
    b.push_str(t("Embedding Model", zh));
    b.push_str("</label>");
    push_default_model_selector(&mut b, &SKILL_EMBD_SELECTOR_FIELD, zh);
    // Upstream `search-config-modal.tsx`: weight/threshold sliders with a live
    // type label, Top K (1..100) and the per-field index weight editor.
    b.push_str("<label style='display:flex;justify-content:space-between;align-items:center'>");
    b.push_str(t("Vector Similarity Weight", zh));
    b.push_str("<span id='skillWeightLabel' class='user-setting-description' style='margin:0'></span></label><input id='skillVectorWeight' type='range' min='0' max='1' step='0.1' value='0.3' style='width:100%' oninput='skillRenderWeightLabel()'><div class='user-setting-description' style='margin:0;display:flex;justify-content:space-between'><span>");
    b.push_str(t("Keyword Only", zh));
    b.push_str("</span><span>");
    b.push_str(t("Balanced", zh));
    b.push_str("</span><span>");
    b.push_str(t("Vector Only", zh));
    b.push_str("</span></div><label style='display:flex;justify-content:space-between;align-items:center'>");
    b.push_str(t("Similarity Threshold", zh));
    b.push_str("<span id='skillThresholdLabel' class='user-setting-description' style='margin:0'></span></label><input id='skillThreshold' type='range' min='0' max='1' step='0.05' value='0.2' style='width:100%' oninput='skillRenderThresholdLabel()'><label>");
    b.push_str(t("Top K Results", zh));
    b.push_str("</label><input id='skillTopK' type='number' min='1' max='100' value='10'><label class='set-title' style='margin-top:12px'>");
    b.push_str(t("Index Fields", zh));
    b.push_str("</label><p class='user-setting-description' style='margin:0 0 8px'>");
    b.push_str(t("Select which fields to include in the search index", zh));
    b.push_str("</p><div id='skillFieldRows'></div><div style='display:flex;gap:8px;margin-top:16px'><button class='btn btn-p' onclick='saveSkillConfig()'>Save</button><button class='btn btn-o' onclick='document.getElementById(&quot;skillConfigModal&quot;).classList.remove(&quot;show&quot;)'>Cancel</button></div></div></div>");
    b.push_str("<script>const MODEL_FIELDS=");
    let skill_fields_payload = serde_json::json!([
        {
            "fieldId": "embd_id",
            "domId": "skillEmbd",
            "updateType": "embd_id",
            "responseType": "embedding",
            "acceptedTypes": ["embedding"],
            "required": true,
            "placeholder": "Select an embedding model",
        }
    ]);
    b.push_str(&json_script_value(&skill_fields_payload));
    b.push_str(DEFAULT_MODEL_TREE_JS_HEAD);
    b.push_str(DEFAULT_MODEL_TREE_JS_BODY);
    b.push_str("function normalizeDefaultModelStoredValues(){MODEL_FIELDS.forEach(function(field){var trigger=document.getElementById(field.domId);if(!trigger)return;var value=trigger.dataset.value||'';if(!value||parseDefaultModelValue(value))return;var parts=value.split('/');if(parts.length!==3)return;var match=DEFAULT_MODEL_CATALOG.find(function(item){return item.name===parts[2]&&item.instance_id===parts[1]&&item.provider_id===parts[0]});if(!match)return;trigger.dataset.value=match.selector;trigger.dataset.savedValue=match.selector;renderDefaultModelTrigger(field)})}async function saveModelDefault(type,nextValue){var field=modelField(type);if(!field)return;var trigger=document.getElementById(field.domId);if(!trigger)return;var state=defaultModelState(field);if(state.pending)return;var value=String(nextValue==null?'':nextValue).trim();if(value&&!defaultModelOption(field,value))return;var previous=trigger.dataset.savedValue||'';trigger.dataset.value=value;if(!value){trigger.dataset.savedValue='';renderDefaultModelTrigger(field);return}var parsed=parseDefaultModelValue(value);if(!parsed){trigger.dataset.value=previous;trigger.dataset.savedValue=previous;renderDefaultModelTrigger(field);return}trigger.dataset.savedValue=value;var typeMap={embd_id:'embedding'};var persistType=typeMap[type];if(!persistType){renderDefaultModelTrigger(field);return}state.pending=true;fetch('/api/v1/models/default',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({model_type:persistType,model_provider:parsed.model_provider,model_instance:parsed.model_instance,model_name:parsed.model_name})}).then(function(response){return response.json()}).then(function(data){state.pending=false;if(data&&data.code===0){renderDefaultModelTrigger(field)}else{trigger.dataset.value=previous;trigger.dataset.savedValue=previous;renderDefaultModelTrigger(field)}}).catch(function(){state.pending=false;trigger.dataset.value=previous;trigger.dataset.savedValue=previous;renderDefaultModelTrigger(field)})}async function loadSkillModelCatalog(){try{var response=await fetch('/api/v1/models');var data=await response.json();if(!response.ok||data.code!==0)return;DEFAULT_MODEL_CATALOG=(data.data||[]).map(normalizeDefaultModel).filter(function(model){return model.selector});MODEL_FIELDS.forEach(function(field){var state=defaultModelState(field);state.expanded.clear();expandDefaultModelTree(field);renderDefaultModelTrigger(field);renderDefaultModelTree(field)});normalizeDefaultModelStoredValues()}catch(error){}}loadSkillModelCatalog();</script>");
    let skill_labels = serde_json::json!({
        "pureKeyword": t("Keyword Only", zh),
        "pureVector": t("Vector Only", zh),
        "hybrid": t("Hybrid", zh),
        "keyword": t("Keyword", zh),
        "vector": t("Vector", zh),
        "weight": t("Weight", zh),
        "fieldName": t("Name", zh),
        "fieldNameDesc": t("Skill name", zh),
        "fieldTags": t("Tags", zh),
        "fieldTagsDesc": t("Skill tags", zh),
        "fieldDescription": t("Description", zh),
        "fieldDescriptionDesc": t("Skill description", zh),
        "fieldContent": t("Content", zh),
        "fieldContentDesc": t("Skill content (e.g., README)", zh),
    });
    b.push_str("<script>var SKILL_LABELS=");
    b.push_str(&serde_json::to_string(&skill_labels).expect("skill labels serialize"));
    b.push_str(";</script>");
    b.push_str("<script>var SKILL_EMBD_REQUIRED=");
    b.push_str(&json_script_string(t(
        "Please select an embedding model",
        zh,
    )));
    b.push_str(";</script>");
    b.push_str(r#"<script>
function skillSpace(){return document.getElementById('skillSpace').value.trim()||'default'}
function esc(v){return String(v==null?'':v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function searchSkills(){var q=document.getElementById('skillQuery').value;fetch('/api/v1/skills/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({space_id:skillSpace(),query:q,page:1,page_size:50})}).then(r=>r.json()).then(function(d){if(d.code!==0){throw new Error(d.message||'Search failed')}var data=d.data||{},skills=data.skills||[];document.getElementById('skillMeta').textContent=(data.total||0)+' skills · '+(data.search_type||'keyword');var h='';skills.forEach(function(s){h+='<div class="kb-card"><div class="av-lg">'+esc((s.name||'S').charAt(0).toUpperCase())+'</div><h3>'+esc(s.name)+'</h3><p style="color:var(--tm);font-size:12px">'+esc(s.description||'')+'</p><p style="font-size:12px">'+(s.tags||[]).map(function(t){return '<span class="badge">'+esc(t)+'</span>'}).join(' ')+'</p><p style="color:var(--tm);font-size:11px">v'+esc(s.version||'1.0.0')+' · score '+Number(s.score||0).toFixed(3)+'</p><button class="btn btn-d btn-sm" onclick="deleteSkill('+JSON.stringify(s.skill_id)+')">Delete index</button></div>'});document.getElementById('skillList').innerHTML=h||'<p style="color:var(--tm)">No skills indexed in this space.</p>'}).catch(function(e){document.getElementById('skillList').innerHTML='<p style="color:var(--danger)">'+esc(e.message)+'</p>'})}
function openSkillModal(){document.getElementById('skillModal').classList.add('show')}
function closeSkillModal(){document.getElementById('skillModal').classList.remove('show')}
function indexSkill(){var tags=document.getElementById('skillTags').value.split(',').map(function(v){return v.trim()}).filter(Boolean);var body={space_id:skillSpace(),skills:[{id:document.getElementById('skillId').value,name:document.getElementById('skillName').value,folder_id:document.getElementById('skillFolder').value,version:document.getElementById('skillVersion').value,tags:tags,description:document.getElementById('skillDescription').value,content:document.getElementById('skillContent').value}]};fetch('/api/v1/skills/index',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json()).then(function(d){if(d.code!==0)throw new Error(d.message||'Index failed');closeSkillModal();searchSkills()}).catch(function(e){alert(e.message)})}
function deleteSkill(id){if(!confirm('Delete this skill index?'))return;fetch('/api/v1/skills/index?space_id='+encodeURIComponent(skillSpace())+'&skill_id='+encodeURIComponent(id),{method:'DELETE'}).then(r=>r.json()).then(function(d){if(d.code!==0)throw new Error(d.message||'Delete failed');searchSkills()}).catch(function(e){alert(e.message)})}
var SKILL_FIELD_SPECS=[['name','Name','Skill name',3],['tags','Tags','Skill tags',2],['description','Description','Skill description',1],['content','Content','Skill content (e.g., README)',0.5]];
function skillRenderWeightLabel(){var weight=Number(document.getElementById('skillVectorWeight').value);var label=document.getElementById('skillWeightLabel');if(!label)return;if(weight===0){label.textContent=SKILL_LABELS.pureKeyword}else if(weight===1){label.textContent=SKILL_LABELS.pureVector}else{label.textContent=SKILL_LABELS.hybrid+' ('+Math.round((1-weight)*100)+'% '+SKILL_LABELS.keyword+' + '+Math.round(weight*100)+'% '+SKILL_LABELS.vector+')'}}
function skillRenderThresholdLabel(){var value=Number(document.getElementById('skillThreshold').value);var label=document.getElementById('skillThresholdLabel');if(label)label.textContent=value.toFixed(1)}
function skillRenderFieldRows(config){var host=document.getElementById('skillFieldRows');if(!host)return;config=config||{};host.replaceChildren();SKILL_FIELD_SPECS.forEach(function(spec){var key=spec[0];var entry=config[key]||{};var enabled=entry.enabled==null?key!=='content':!!entry.enabled;var weight=entry.weight==null?spec[3]:entry.weight;var row=document.createElement('div');row.className='set-switch skill-field-row';row.style.marginTop='6px';var box=document.createElement('input');box.type='checkbox';box.id='skillField-'+key;box.checked=enabled;var label=document.createElement('span');label.className='set-sw-label';label.textContent=SKILL_LABELS['field'+key.charAt(0).toUpperCase()+key.slice(1)]||spec[1];var desc=document.createElement('span');desc.className='user-setting-description';desc.style.margin='0';desc.textContent=SKILL_LABELS['field'+key.charAt(0).toUpperCase()+key.slice(1)+'Desc']||spec[2];var weightInput=document.createElement('input');weightInput.type='number';weightInput.id='skillFieldWeight-'+key;weightInput.min='0';weightInput.step='0.5';weightInput.value=String(weight);weightInput.style.maxWidth='90px';weightInput.setAttribute('aria-label',SKILL_LABELS.weight+' '+spec[1]);row.appendChild(box);row.appendChild(label);row.appendChild(desc);row.appendChild(weightInput);host.appendChild(row)})}
function openSkillConfig(){fetch('/api/v1/skills/config?space_id='+encodeURIComponent(skillSpace())).then(r=>r.json()).then(function(d){var c=d.data||{};var skillTrigger=document.getElementById('skillEmbd');skillTrigger.dataset.value=c.embd_id||'';skillTrigger.dataset.savedValue=skillTrigger.dataset.value;var skillField=modelField('embd_id');if(skillField){renderDefaultModelTrigger(skillField);renderDefaultModelTree(skillField)}normalizeDefaultModelStoredValues();document.getElementById('skillVectorWeight').value=c.vector_similarity_weight==null?0.3:c.vector_similarity_weight;document.getElementById('skillThreshold').value=c.similarity_threshold==null?0.2:c.similarity_threshold;document.getElementById('skillTopK').value=c.top_k||10;skillRenderFieldRows(c.field_config||{});skillRenderWeightLabel();skillRenderThresholdLabel();document.getElementById('skillConfigModal').classList.add('show')})}
function saveSkillConfig(){var skillVal=(document.getElementById('skillEmbd').dataset.value||'');if(!skillVal){alert(SKILL_EMBD_REQUIRED);return}var fields={};SKILL_FIELD_SPECS.forEach(function(spec){var key=spec[0];var box=document.getElementById('skillField-'+key);var weightInput=document.getElementById('skillFieldWeight-'+key);fields[key]={enabled:box?!!box.checked:false,weight:weightInput?(Number(weightInput.value)||0):spec[3]}});var body={space_id:skillSpace(),embd_id:skillVal,vector_similarity_weight:Number(document.getElementById('skillVectorWeight').value),similarity_threshold:Number(document.getElementById('skillThreshold').value),top_k:Number(document.getElementById('skillTopK').value),field_config:fields};fetch('/api/v1/skills/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}).then(r=>r.json()).then(function(d){if(d.code!==0)throw new Error(d.message||'Save failed');document.getElementById('skillConfigModal').classList.remove('show');searchSkills()}).catch(function(e){alert(e.message)})}
function reindexSkills(){if(!confirm('Re-embed all indexed skills in this space?'))return;fetch('/api/v1/skills/reindex',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({space_id:skillSpace()})}).then(r=>r.json()).then(function(d){if(d.code!==0)throw new Error(d.message||'Reindex failed');alert('Reindexed '+(d.data.indexed_count||0)+' skills · '+d.data.version);searchSkills()}).catch(function(e){alert(e.message)})}
searchSkills();
</script>"#);
    Html(layout(t("Skills", zh), &b, zh))
}

#[derive(Clone, Copy)]
struct DefaultModelField {
    field_id: &'static str,
    dom_id: &'static str,
    /// Upstream `setting.*Model` label (`system-setting.tsx` `ModelFieldItem`).
    label: &'static str,
    /// Same label from `locales/zh.ts`; `LLM`/`VLM`/`ASR`/`TTS` stay English
    /// there, `embeddingModel`/`rerankModel` are translated.
    label_zh: &'static str,
    update_type: &'static str,
    response_type: &'static str,
    accepted_types: &'static [&'static str],
    required: bool,
    tooltip: &'static str,
    placeholder: &'static str,
}

